package com.example.service

import android.content.Context
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.graphics.RectF
import android.graphics.pdf.PdfDocument
import com.example.data.model.StoryboardScene
import java.io.File
import java.io.FileOutputStream
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

object PdfExporter {

    /**
     * Generates a PDF storyboard deck from scenes and saves it to app storage.
     * Returns the generated file path.
     */
    fun exportStoryboardDeck(
        context: Context,
        scriptTitle: String,
        scenes: List<StoryboardScene>
    ): Result<String> {
        return try {
            val pdfDoc = PdfDocument()
            val pageWidth = 595 // A4 standard width in points at 72 dpi
            val pageHeight = 842 // A4 standard height

            val titlePaint = Paint().apply {
                color = Color.rgb(14, 22, 38) // Deep Navy
                textSize = 22f
                isFakeBoldText = true
                isAntiAlias = true
            }

            val subtitlePaint = Paint().apply {
                color = Color.rgb(100, 110, 125)
                textSize = 11f
                isAntiAlias = true
            }

            val headingPaint = Paint().apply {
                color = Color.rgb(20, 30, 45)
                textSize = 13f
                isFakeBoldText = true
                isAntiAlias = true
            }

            val textPaint = Paint().apply {
                color = Color.rgb(40, 40, 45)
                textSize = 10f
                isAntiAlias = true
            }

            val badgeBgPaint = Paint().apply {
                color = Color.rgb(220, 230, 245)
                style = Paint.Style.FILL
                isAntiAlias = true
            }

            val badgeTextPaint = Paint().apply {
                color = Color.rgb(30, 60, 120)
                textSize = 9f
                isFakeBoldText = true
                isAntiAlias = true
            }

            val boxPaint = Paint().apply {
                color = Color.rgb(200, 205, 215)
                style = Paint.Style.STROKE
                strokeWidth = 1f
                isAntiAlias = true
            }

            val sketchBgPaint = Paint().apply {
                color = Color.rgb(245, 245, 248)
                style = Paint.Style.FILL
            }

            var pageNum = 1
            var pageInfo = PdfDocument.PageInfo.Builder(pageWidth, pageHeight, pageNum).create()
            var page = pdfDoc.startPage(pageInfo)
            var canvas: Canvas = page.canvas

            // Cover / Header banner
            canvas.drawText("STORYBOARD DECK: $scriptTitle", 40f, 50f, titlePaint)
            val dateStr = SimpleDateFormat("MMMM dd, yyyy", Locale.US).format(Date())
            canvas.drawText("Generated by StoryFlip Director Studio • $dateStr • Page $pageNum", 40f, 68f, subtitlePaint)
            canvas.drawLine(40f, 78f, (pageWidth - 40).toFloat(), 78f, boxPaint)

            var currentY = 100f
            val cardHeight = 150f

            for (scene in scenes) {
                for (shot in scene.shots) {
                    // Check if new page is needed
                    if (currentY + cardHeight > pageHeight - 50) {
                        pdfDoc.finishPage(page)
                        pageNum++
                        pageInfo = PdfDocument.PageInfo.Builder(pageWidth, pageHeight, pageNum).create()
                        page = pdfDoc.startPage(pageInfo)
                        canvas = page.canvas
                        currentY = 50f

                        // Top mini header
                        canvas.drawText("$scriptTitle — Page $pageNum", 40f, currentY, subtitlePaint)
                        currentY += 25f
                        canvas.drawLine(40f, currentY, (pageWidth - 40).toFloat(), currentY, boxPaint)
                        currentY += 20f
                    }

                    // Draw shot card container
                    val cardRect = RectF(40f, currentY, (pageWidth - 40).toFloat(), currentY + cardHeight)
                    canvas.drawRoundRect(cardRect, 8f, 8f, boxPaint)

                    // Left sketch preview area
                    val sketchRect = RectF(48f, currentY + 8f, 180f, currentY + cardHeight - 8f)
                    canvas.drawRoundRect(sketchRect, 6f, 6f, sketchBgPaint)
                    canvas.drawRoundRect(sketchRect, 6f, 6f, boxPaint)

                    // Draw cinematic aspect ratio guides and shot label
                    canvas.drawText("SHOT ${shot.shotNumber}", 55f, currentY + 30f, headingPaint)
                    canvas.drawText("[${shot.shotType.label}]", 55f, currentY + 48f, badgeTextPaint)
                    canvas.drawText("Move: ${shot.cameraMovement.label}", 55f, currentY + 66f, subtitlePaint)

                    // Content on the right
                    val textStartX = 195f
                    canvas.drawText("SCENE ${shot.sceneNumber}: ${scene.heading.take(45)}", textStartX, currentY + 28f, headingPaint)

                    // Badges
                    val badgeRect = RectF(textStartX, currentY + 36f, textStartX + 90f, currentY + 50f)
                    canvas.drawRoundRect(badgeRect, 4f, 4f, badgeBgPaint)
                    canvas.drawText(shot.shotType.label, textStartX + 6f, currentY + 46f, badgeTextPaint)

                    // Action description
                    canvas.drawText("ACTION:", textStartX, currentY + 68f, subtitlePaint)
                    val actionLine1 = shot.actionNotes.take(65)
                    val actionLine2 = if (shot.actionNotes.length > 65) shot.actionNotes.drop(65).take(65) else ""
                    canvas.drawText(actionLine1, textStartX, currentY + 82f, textPaint)
                    if (actionLine2.isNotBlank()) {
                        canvas.drawText(actionLine2, textStartX, currentY + 95f, textPaint)
                    }

                    // Dialogue if present
                    if (!shot.dialogue.isNullOrBlank()) {
                        canvas.drawText("DIALOGUE:", textStartX, currentY + 115f, subtitlePaint)
                        canvas.drawText(shot.dialogue.take(65), textStartX, currentY + 128f, textPaint)
                    } else {
                        canvas.drawText("PROMPT: ${shot.visualPrompt.take(60)}", textStartX, currentY + 120f, subtitlePaint)
                    }

                    currentY += cardHeight + 15f
                }
            }

            pdfDoc.finishPage(page)

            // Save PDF file to cache/export folder
            val exportDir = File(context.filesDir, "storyboard_exports").apply { mkdirs() }
            val cleanTitle = scriptTitle.replace("[^a-zA-Z0-9]".toRegex(), "_").take(25)
            val outFile = File(exportDir, "${cleanTitle}_storyboard_${System.currentTimeMillis()}.pdf")
            val outputStream = FileOutputStream(outFile)
            pdfDoc.writeTo(outputStream)
            outputStream.flush()
            outputStream.close()
            pdfDoc.close()

            Result.success(outFile.absolutePath)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}
